const storeFoodChangedAt = `-- name: StoreFoodChangedAt :many
SELECT store_id,
       MAX(CASE WHEN state = 'APPROVED' THEN decided_at WHEN end_cause IN ('CLEARED', 'REVOKED') THEN ended_at END)::timestamptz AS food_changed_at
FROM seller.food_registrations
WHERE store_id = ANY($1::bigint[]) AND (state = 'APPROVED' OR end_cause IN ('CLEARED', 'REVOKED'))
GROUP BY store_id
`

type StoreFoodChangedAtRow struct {
	StoreID       int64
	FoodChangedAt time.Time
}

// 這些店家的公開字號最後一次改變的時間：目前核准那一筆的核准時間，與最近一次賣家清除或平台撤銷的結束時間，取較晚的；從來沒有核准、清除或撤銷過的
// 店家沒有列。給公開資料的 update_time（model.PublicStoreUpdateTime）。被取代的舊核准結束時，新的核准時間就是同一刻。
func (q *Queries) StoreFoodChangedAt(ctx context.Context, storeIds []int64) ([]StoreFoodChangedAtRow, error) {
	rows, err := q.db.Query(ctx, storeFoodChangedAt, storeIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StoreFoodChangedAtRow{}
	for rows.Next() {
		var i StoreFoodChangedAtRow
		if err := rows.Scan(&i.StoreID, &i.FoodChangedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const storeFoodRegistrations = `-- name: StoreFoodRegistrations :many
SELECT f.id, f.store_id, f.account_id, f.registration_number, f.state, f.submitted_at, f.decided_by_admin_id, f.decided_at, f.reject_reason, f.internal_note, f.ended_at, f.end_cause, f.end_reason, f.ended_by_admin_id, f.pii_purged_at
FROM seller.food_registrations f
WHERE f.store_id = ANY($1::bigint[])
  AND (f.state = 'APPROVED'
       OR f.id = (
        SELECT l.id FROM seller.food_registrations l
        WHERE l.store_id = f.store_id
        ORDER BY l.submitted_at DESC, l.id DESC
        LIMIT 1))
ORDER BY f.store_id, f.submitted_at, f.id
`

// 一批店家各自核准的那一筆與賣家看得到的登錄（最近送出的那一筆，狀態是 PENDING 或 REJECTED 才算；判斷在呼叫方），每店最多兩列。
func (q *Queries) StoreFoodRegistrations(ctx context.Context, storeIds []int64) ([]SellerFoodRegistration, error) {
	rows, err := q.db.Query(ctx, storeFoodRegistrations, storeIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SellerFoodRegistration{}
	for rows.Next() {
		var i SellerFoodRegistration
		if err := rows.Scan(
			&i.ID,
			&i.StoreID,
			&i.AccountID,
			&i.RegistrationNumber,
			&i.State,
			&i.SubmittedAt,
			&i.DecidedByAdminID,
			&i.DecidedAt,
			&i.RejectReason,
			&i.InternalNote,
			&i.EndedAt,
			&i.EndCause,
			&i.EndReason,
			&i.EndedByAdminID,
			&i.PiiPurgedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const storeRevokedFoodRegistrations = `-- name: StoreRevokedFoodRegistrations :many
SELECT r.id, r.store_id, r.account_id, r.registration_number, r.state, r.submitted_at, r.decided_by_admin_id, r.decided_at, r.reject_reason, r.internal_note, r.ended_at, r.end_cause, r.end_reason, r.ended_by_admin_id, r.pii_purged_at
FROM (
    SELECT DISTINCT ON (x.store_id) x.id, x.store_id, x.account_id, x.registration_number, x.state, x.submitted_at, x.decided_by_admin_id, x.decided_at, x.reject_reason, x.internal_note, x.ended_at, x.end_cause, x.end_reason, x.ended_by_admin_id, x.pii_purged_at
    FROM seller.food_registrations x
    WHERE x.store_id = ANY($1::bigint[]) AND x.end_cause = 'REVOKED'
    ORDER BY x.store_id, x.ended_at DESC, x.id DESC
) r
WHERE NOT EXISTS (
    SELECT 1 FROM seller.food_registrations g
    WHERE g.store_id = r.store_id AND g.id <> r.id
      AND ((g.state = 'PENDING' AND g.submitted_at > r.ended_at)
           OR (g.state IN ('APPROVED', 'ENDED') AND g.decided_at > r.ended_at)))
ORDER BY r.store_id
`

