const withdrawPendingFoodRegistrations = `-- name: WithdrawPendingFoodRegistrations :many
UPDATE seller.food_registrations f
SET state = 'WITHDRAWN', ended_at = $1::timestamptz
FROM seller.stores s
WHERE f.store_id = ANY($2::bigint[]) AND s.store_id = f.store_id AND s.retired_at IS NOT NULL AND f.state = 'PENDING'
RETURNING f.store_id
`

type WithdrawPendingFoodRegistrationsParams struct {
	Now      time.Time
	StoreIds []int64
}

// 店家退場（第一段清理，之後不會再重開）時撤回這些店家待審的登錄；沒有待審的店家沒有列。只作用於店家列已退場的店家。
func (q *Queries) WithdrawPendingFoodRegistrations(ctx context.Context, arg WithdrawPendingFoodRegistrationsParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, withdrawPendingFoodRegistrations, arg.Now, arg.StoreIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var store_id int64
		if err := rows.Scan(&store_id); err != nil {
			return nil, err
		}
		items = append(items, store_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
